import{_ as t,o as a,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const k=JSON.parse('{"title":"Plan — FR 3.6.1 / DA-978","description":"","frontmatter":{},"headers":[],"relativePath":"feature/content-task-workflow/3-6-1-identify-task-detail/plan.md","filePath":"feature/content-task-workflow/3-6-1-identify-task-detail/plan.md"}'),o={name:"feature/content-task-workflow/3-6-1-identify-task-detail/plan.md"};function r(s,e,c,h,l,d){return a(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="plan-—-fr-3-6-1-da-978" tabindex="-1">Plan — FR 3.6.1 / DA-978 <a class="header-anchor" href="#plan-—-fr-3-6-1-da-978" aria-label="Permalink to &quot;Plan — FR 3.6.1 / DA-978&quot;">​</a></h1><p>&gt; <strong>Ưu tiên BA mới 2026-10-15:</strong> xem <a href="./../task-five-state-inline-edit/spec.html">Task năm trạng thái + inline autosave</a>. TODO thay BACKLOG/DETAIL_IDENTIFIED/ASSIGNED; giao việc cần mô tả + deadline hợp lệ, không chuyển trạng thái. IN_REVIEW lưu bước QC/Manager/Client riêng, reject về IN_PROGRESS, bước cuối thành công mới FINISHED. Manager khóa sửa/giao lại sau lần bắt đầu đầu tiên. Phần vòng đời/form cũ bên dưới được giữ làm lịch sử, không phải contract mới. Đợt này chỉ code FR 3.6.1/2; Approval và Comments không được coi là đã hoàn thành.</p><h2 id="đieu-chinh-ui-đa-đuoc-yeu-cau-2026-10-15" tabindex="-1">Điều chỉnh UI đã được yêu cầu 2026-10-15 <a class="header-anchor" href="#đieu-chinh-ui-đa-đuoc-yeu-cau-2026-10-15" aria-label="Permalink to &quot;Điều chỉnh UI đã được yêu cầu 2026-10-15&quot;">​</a></h2><p>Thay dialog tóm tắt + trang detail bằng TaskDetailPanel trên danh sách. Tách workflow content khỏi PageWrapper; QueryClientProvider riêng theo Workspace/Task, mutation callback refresh useTasks. Desktop dùng aside không modal, màn hình nhỏ dùng Sheet với focus trap; cả hai tái sử dụng nội dung/form. Chọn Task qua query parameter task, giữ nguyên query khác và state của list; route detail cũ redirect. Các link từ Campaign/Request chỉ đổi đích tới list?task. Không đổi API/DB/editor/ACL.</p><p>File UI: pages/tasks/index.tsx, detail.tsx, components/TaskDetailPanel.tsx, TaskWorkflowContent.tsx, hooks/useTaskPanel.ts, TaskTable.tsx; locale src/i18n/locales/{vi,en}/tasks.json. Giữ tone BrandHub: font/token sẵn có, nền card/background, border phân cột, orange chỉ cho hành động/Task được chọn; không thêm palette/font. Kiểm tra browser mock desktop/mobile, đóng/mở/switch Task, mutation, focus, Back/Forward và direct link; kiểm thử provider dùng component thật không bọc provider từ test.</p><p>2026-10-14. <a href="./spec.html">Spec confirmed, Q13 mới nhất</a>. Mục tiêu: Manager chuẩn bị brief trước Creator bắt đầu. Thiết kế giai đoạn 1, chưa có API/UI triển khai; dùng <a href="./../task-workflow-contract.html">contract chung</a>.</p><h2 id="pham-vi-va-model" tabindex="-1">Phạm vi và model <a class="header-anchor" href="#pham-vi-va-model" aria-label="Permalink to &quot;Phạm vi và model&quot;">​</a></h2><p>Business đọc TaskDocument Mongo, Workspace membership/ClientProfile và Campaign PostgreSQL. Thêm TaskWorkflowController/Service/Access/Store + DTO riêng; không thay TaskResponse/editor legacy SQL. Task optional fields theo contract §2; migration foundation + init/checker, không backfill lịch sử start. POST plannedPublishAt tách dueDate; inputReferences không ghi đè typeMetadata.</p><h2 id="api-final-cho-phan-đa-chot" tabindex="-1">API final cho phần đã chốt <a class="header-anchor" href="#api-final-cho-phan-đa-chot" aria-label="Permalink to &quot;API final cho phần đã chốt&quot;">​</a></h2><p>GET <code>.../tasks/{taskId}/workflow</code>, GET <code>.../tasks/workflow</code> (list tối thiểu cần review E51-05), GET <code>.../tasks/{taskId}/member-options</code>, PATCH <code>.../tasks/{taskId}/detail</code>. Payload PATCH gồm description, dueDate, optional plannedPublishAt, inputReferences, expectedRevision; trả workflow DTO, status uppercase. Chi tiết và errors theo contract §3. Q13: đọc workflow theo active Workspace membership, Client đọc mọi nguồn Task, kể cả manual/legacy. Không có visibility trong schema/DTO/payload hoặc Q12 validation. Quyền đọc/bình luận không cấp quyền sửa/editor.</p><h2 id="xu-ly" tabindex="-1">Xử lý <a class="header-anchor" href="#xu-ly" aria-label="Permalink to &quot;Xử lý&quot;">​</a></h2><p>Auth + scope + quyền → legacy/start/status guard cho mutation → Campaign lock → date validation theo Workspace → CAS/targeted update → BACKLOG thành DETAIL_IDENTIFIED lần đầu; lần sửa sau giữ status/assignee. Không sửa Campaign plan, approvalRound, cancellation, source hoặc specialist content. Legacy thiếu lịch sử bắt đầu không tự coi chưa bắt đầu; phải inventory/review trước sửa/giao lại, nhưng không lấy thiếu marker/revision làm lý do chặn Client xem/bình luận Task cùng Workspace.</p><h2 id="frontend-i18n-va-theme" tabindex="-1">Frontend, i18n và theme <a class="header-anchor" href="#frontend-i18n-va-theme" aria-label="Permalink to &quot;Frontend, i18n và theme&quot;">​</a></h2><p>Module <code>src/pages/tasks/</code> + service/hooks/types; route <code>/workspaces/:id/tasks/:taskId/detail</code>. Locale <code>src/locales/vi/tasks.json</code> và <code>src/locales/en/tasks.json</code> + registry theo repo thực tế. Keys detail/fields/status/actions/errors/common; semantic theme, keyboard/focusable error summary + inline errors, date min/max, giữ draft khi 409. Không đổi editor/views toàn hệ thống.</p><h2 id="dependencies-trinh-tu-va-rui-ro" tabindex="-1">Dependencies, trình tự và rủi ro <a class="header-anchor" href="#dependencies-trinh-tu-va-rui-ro" aria-label="Permalink to &quot;Dependencies, trình tự và rủi ro&quot;">​</a></h2><p>Schema/ACL → API đọc → form → mutation/validation/CAS → integration regression. Phối hợp E51-03 firstStartedAt và writer trạng thái; E51-05 list; editor auto-create source defaults. Rủi ro: legacy thiếu marker; ClientProfile resolve; nhầm quyền đọc/bình luận thành quyền editor; timezone/ngày hết hạn; Mongo/SQL không distributed ACID; cancellation đua với detail. Xem <a href="./task.html">task</a> và <a href="./test.html">test</a>; không coi schema pass là FR Done.</p><h2 id="implementation-slice-2026-10-15" tabindex="-1">Implementation slice 2026-10-15 <a class="header-anchor" href="#implementation-slice-2026-10-15" aria-label="Permalink to &quot;Implementation slice 2026-10-15&quot;">​</a></h2><p>Reuse GET tasks của DA-979 thay GET /tasks/workflow thứ hai. Thêm GET /{taskId}/workflow và member-options, PATCH detail. Date bounds/timezone/campaign state do backend trả; input datetime-local được chuyển chính xác từ timezone Workspace, từ chối giờ DST không tồn tại. DTO không expose specialist content. Mongo raw presence phân biệt missing marker với explicit null; writer mới khởi tạo metadata, không tự đổi legacy. Targeted update CAS cả revision/status/updatedAt; mutation Campaign dùng SQL agreement lock và Mongo transaction. Locale thực tế: src/i18n/locales/{vi,en}/tasks.json. Link từ List/Campaign/Request vào route detail; các editor links vẫn giữ nguyên.</p>',18)])])}const p=t(o,[["render",r]]);export{k as __pageData,p as default};
